body.query:
query TaxonSearch(
  $offset: Int
  $limit: Int
  $query: TaxonSearchInput
  $sortBy: TaxonSearchSortBy
  $reverse: Boolean
) {
  taxonSearch(query: $query, offset: $offset, limit: $limit, sortBy: $sortBy, reverse: $reverse) {
    count
    offset
    endOfRecords
    results {
      taxonID
      fallbackID
      scientificName
      label
      taxonomicStatus
      taxonRank
      datasetKey
      dataset {
        title
      }
      acceptedNameUsageID
      classification {
        scientificName
        taxonRank
      }
      vernacularName(language: "eng") {
        vernacularName
      }
    }
  }
}
